#!/usr/bin/env Rscript
# ============================================================================
# Arabidopsis mRNA GO enrichment bar plots (sci-plot GO template)
# Input: one-column, headerless TAIR gene-ID TSVs generated by data_prep.sh
# ============================================================================

ORG_DB          <- "org.At.tair.db"
FROM_TYPE       <- "TAIR"
ONTOLOGY        <- "all"
PVALUE_CUTOFF   <- 0.05
QVALUE_CUTOFF   <- 0.05
SIMPLIFY_CUTOFF <- 0.7
TOP_N           <- 5
STRIP_TAIL      <- TRUE

suppressPackageStartupMessages({
  library(clusterProfiler)
  library(dplyr)
  library(DOSE)
  library(ggplot2)
  library(tidyr)
  library(forcats)
  library(ggprism)
  library(stringr)
})

get_script_dir <- function() {
  cmd_args <- commandArgs(trailingOnly = FALSE)
  file_arg <- "--file="
  script_path <- cmd_args[grepl(file_arg, cmd_args)]
  if (length(script_path) > 0) {
    return(dirname(normalizePath(sub(file_arg, "", script_path[1]))))
  }
  normalizePath(getwd())
}

script_dir <- get_script_dir()
setwd(script_dir)

gene_tsvs <- c(
  Root_unique   = file.path(script_dir, "root_unique_gene_list.tsv"),
  Leaf_unique   = file.path(script_dir, "leaf_unique_gene_list.tsv"),
  Flower_unique = file.path(script_dir, "flower_unique_gene_list.tsv"),
  Common        = file.path(script_dir, "common_gene_list.tsv"),
  Roots         = file.path(script_dir, "root_all_gene_list.tsv"),
  Leaves        = file.path(script_dir, "leaf_all_gene_list.tsv"),
  Flowers       = file.path(script_dir, "flower_all_gene_list.tsv")
)

group_labels <- c(
  Root_unique   = "Root-unique",
  Leaf_unique   = "Leaf-unique",
  Flower_unique = "Flower-unique",
  Common        = "Common",
  Roots         = "Roots",
  Leaves        = "Leaves",
  Flowers       = "Flowers"
)

# The combined figure only contrasts the three whole-tissue groups: each column
# is the GO enrichment of ALL modified mRNAs (genes) detected in that tissue.
combined_groups <- c("Roots", "Leaves", "Flowers")

ont_order <- c("BP", "CC", "MF")
style_file <- file.path(script_dir, "..", "..", "shared", "plot_style.R")
if (!file.exists(style_file)) stop("plot_style.R not found: ", style_file)
source(style_file)
init_theme_offset()

if (!requireNamespace(ORG_DB, quietly = TRUE)) stop("OrgDb not installed: ", ORG_DB)
library(ORG_DB, character.only = TRUE)
orgDb <- get(ORG_DB)

read_gene_ids <- function(gene_tsv) {
  if (!file.exists(gene_tsv)) stop("Missing gene-ID TSV: ", gene_tsv)
  gene_df <- read.table(
    gene_tsv,
    header = FALSE,
    sep = "\t",
    stringsAsFactors = FALSE,
    comment.char = "",
    colClasses = "character",
    check.names = FALSE
  )
  gene_ids <- gene_df[[1]]
  gene_ids <- gene_ids[!is.na(gene_ids) & gene_ids != ""]
  if (STRIP_TAIL) gene_ids <- sub("\\..*$", "", gene_ids)
  sort(unique(gene_ids))
}

run_go_enrichment <- function(group_name, gene_ids) {
  message("[plot] ", group_name, ": ", length(gene_ids), " input genes")
  if (length(gene_ids) == 0) stop("No input genes for ", group_name)

  mapped <- clusterProfiler::bitr(
    gene_ids,
    fromType = FROM_TYPE,
    toType = "ENTREZID",
    OrgDb = orgDb
  )
  message("[plot] ", group_name, ": ", nrow(mapped), " mapped ENTREZID genes")
  if (nrow(mapped) == 0) stop("No genes mapped to ENTREZID for ", group_name)
  mapped <- dplyr::distinct(mapped, ENTREZID, .keep_all = TRUE)

  go_enrich <- clusterProfiler::enrichGO(
    gene = mapped$ENTREZID,
    ont = ONTOLOGY,
    keyType = "ENTREZID",
    OrgDb = orgDb,
    pAdjustMethod = "BH",
    pvalueCutoff = PVALUE_CUTOFF,
    qvalueCutoff = QVALUE_CUTOFF
  )
  if (is.null(go_enrich) || nrow(go_enrich@result) == 0) {
    message("[plot] No enriched GO terms for ", group_name, "; writing an empty result table")
    result <- go_enrich@result |>
      dplyr::mutate(
        GeneRatio = as.numeric(GeneRatio),
        Group = group_name,
        Group_label = unname(group_labels[[group_name]])
      )
    result_csv <- file.path(
      script_dir,
      paste0(group_name, "_GO_enrichment_bar.csv")
    )
    utils::write.csv(result, result_csv, row.names = FALSE)
    message("[plot] Saved: ", result_csv)
    return(result)
  }

  go_enrich <- DOSE::setReadable(
    go_enrich,
    OrgDb = orgDb,
    keyType = "ENTREZID"
  )
  go_enrich <- clusterProfiler::simplify(
    go_enrich,
    cutoff = SIMPLIFY_CUTOFF,
    by = "p.adjust",
    select_fun = min
  )
  result <- go_enrich@result
  result <- result |>
    tidyr::separate(
      col = GeneRatio,
      into = c("GR1", "GR2"),
      sep = "/",
      remove = FALSE
    ) |>
    dplyr::mutate(
      GeneRatio = as.numeric(GR1) / as.numeric(GR2),
      Group = group_name,
      Group_label = unname(group_labels[[group_name]])
    )

  result_csv <- file.path(
    script_dir,
    paste0(group_name, "_GO_enrichment_bar.csv")
  )
  utils::write.csv(result, result_csv, row.names = FALSE)
  message("[plot] Saved: ", result_csv)
  result
}

enrichment_results <- lapply(names(gene_tsvs), function(group_name) {
  run_go_enrichment(group_name, read_gene_ids(gene_tsvs[[group_name]]))
})
names(enrichment_results) <- names(gene_tsvs)
all_results <- dplyr::bind_rows(enrichment_results)

combined_csv <- file.path(script_dir, "mrna_go_enrichment_bar_results.csv")
all_results |>
  dplyr::filter(Group %in% combined_groups) |>
  utils::write.csv(combined_csv, row.names = FALSE)
message("[plot] Saved: ", combined_csv)

top_results <- all_results |>
  dplyr::group_by(Group, ONTOLOGY) |>
  dplyr::arrange(p.adjust, .by_group = TRUE) |>
  dplyr::slice_head(n = TOP_N) |>
  dplyr::ungroup() |>
  dplyr::mutate(
    Group = factor(Group, levels = names(gene_tsvs)),
    Group_label = factor(Group_label, levels = unname(group_labels)),
    ONTOLOGY = factor(ONTOLOGY, levels = ont_order),
    neg_log10_padj = -log10(p.adjust),
    Description = stringr::str_wrap(Description, width = 35)
  )

build_group_barplot <- function(group_data) {
  group_data <- group_data |>
    dplyr::arrange(ONTOLOGY, dplyr::desc(neg_log10_padj)) |>
    dplyr::mutate(Description = forcats::fct_inorder(Description))

  label_offset <- max(group_data$neg_log10_padj, na.rm = TRUE) * 0.02
  ont_colors <- c("BP" = "#E64B35CC", "CC" = "#F39B7FCC", "MF" = "#8491B4CC")

  ggplot2::ggplot(
    group_data,
    ggplot2::aes(x = .data[["neg_log10_padj"]], y = .data[["Description"]])
  ) +
    ggplot2::geom_bar(
      stat = "identity",
      ggplot2::aes(fill = .data[["ONTOLOGY"]]),
      width = 0.8,
      linewidth = 0.6,
      color = "black"
    ) +
    ggplot2::geom_text(
      ggplot2::aes(label = .data[["Description"]]),
      x = label_offset,
      hjust = 0,
      vjust = 0.5,
      size = 4.5,
      family = "Arial",
      fontface = "bold"
    ) +
    ggplot2::facet_grid(
      ONTOLOGY ~ .,
      scales = "free_y",
      space = "free_y",
      switch = "y"
    ) +
    ggplot2::scale_fill_manual(values = ont_colors, guide = "none") +
    ggplot2::scale_x_continuous(
      expand = ggplot2::expansion(mult = c(0, 0.05)),
      guide = ggprism::guide_prism_offset()
    ) +
    ggplot2::scale_y_discrete(guide = ggprism::guide_prism_offset()) +
    ggplot2::labs(x = "-log10(p.adjust)", y = NULL) +
    ggplot2::theme(
      axis.text.y = ggplot2::element_blank(),
      axis.ticks.y = ggplot2::element_blank(),
      axis.line.y = ggplot2::element_blank(),
      strip.text.y.left = ggplot2::element_text(
        size = 12,
        color = "black",
        face = "bold",
        angle = 0,
        hjust = 0,
        family = "Arial"
      ),
      strip.placement = "outside"
    ) +
    ggplot2::coord_cartesian(clip = "off")
}

build_no_enrichment_plot <- function(group_label) {
  ggplot2::ggplot(data.frame(x = 0, y = 0)) +
    ggplot2::annotate(
      "text",
      x = 0,
      y = 0,
      label = paste0(group_label, ":\nno significant GO terms\n(raw p < 0.05 and BH q < 0.05)"),
      size = 4.5,
      family = "Arial",
      fontface = "bold",
      color = "#4D4D4D"
    ) +
    ggplot2::xlim(-1, 1) +
    ggplot2::ylim(-1, 1) +
    ggplot2::labs(x = "-log10(p.adjust)", y = NULL) +
    ggplot2::theme_void(base_family = "Arial") +
    ggplot2::theme(text = ggplot2::element_text(family = "Arial", colour = "black"))
}

for (group_name in names(gene_tsvs)) {
  group_data <- top_results |> dplyr::filter(Group == .env$group_name)
  output_stem <- paste0(group_name, "_GO_enrichment_bar")
  if (nrow(group_data) == 0) {
    no_enrichment_plot <- build_no_enrichment_plot(unname(group_labels[[group_name]]))
    save_plot(no_enrichment_plot, output_stem, width = 10, height = 5)
    next
  }
  group_plot <- build_group_barplot(group_data)
  plot_height <- max(5, nrow(group_data) * 0.5)
  save_plot(group_plot, output_stem, width = 10, height = plot_height)
}

combined_data <- top_results |>
  dplyr::filter(Group %in% combined_groups) |>
  dplyr::mutate(
    Group = factor(as.character(Group), levels = combined_groups),
    Group_label = factor(
      as.character(Group_label),
      levels = unname(group_labels[combined_groups])
    )
  ) |>
  dplyr::arrange(Group, ONTOLOGY, dplyr::desc(neg_log10_padj)) |>
  dplyr::mutate(term_key = paste(Group, ONTOLOGY, as.character(Description), sep = "||")) |>
  dplyr::mutate(term_key = forcats::fct_inorder(term_key)) |>
  dplyr::group_by(Group, ONTOLOGY) |>
  dplyr::mutate(label_x = max(.data[["neg_log10_padj"]], na.rm = TRUE) * 0.02) |>
  dplyr::ungroup()

ont_colors <- c("BP" = "#E64B35CC", "CC" = "#F39B7FCC", "MF" = "#8491B4CC")
combined_plot <- ggplot2::ggplot(
  combined_data,
  ggplot2::aes(x = .data[["neg_log10_padj"]], y = .data[["term_key"]])
) +
  ggplot2::geom_bar(
    stat = "identity",
    ggplot2::aes(fill = .data[["ONTOLOGY"]]),
    width = 0.8,
    linewidth = 0.6,
    color = "black"
  ) +
  ggplot2::geom_text(
    ggplot2::aes(x = .data[["label_x"]], label = .data[["Description"]]),
    hjust = 0,
    vjust = 0.5,
    size = 4.1,
    family = "Arial",
    fontface = "bold"
  ) +
  ggplot2::facet_grid(
    ONTOLOGY ~ Group_label,
    scales = "free",
    space = "free_y",
    switch = "y",
    drop = FALSE
  ) +
  ggplot2::scale_fill_manual(values = ont_colors, guide = "none") +
  ggplot2::scale_x_continuous(
    expand = ggplot2::expansion(mult = c(0, 0.08)),
    guide = ggprism::guide_prism_offset()
  ) +
  ggplot2::scale_y_discrete(guide = ggprism::guide_prism_offset(), drop = FALSE) +
  ggplot2::labs(
    x = "-log10(p.adjust)",
    y = NULL,
    caption = paste0(
      "No significant GO terms: ",
      paste(
        combined_groups[vapply(
          combined_groups,
          function(group_name) nrow(all_results[all_results$Group == group_name, , drop = FALSE]) == 0,
          logical(1)
        )],
        collapse = ", "
      )
    )
  ) +
  ggplot2::theme(
    axis.text.y = ggplot2::element_blank(),
    axis.ticks.y = ggplot2::element_blank(),
    axis.line.y = ggplot2::element_blank(),
    strip.text.y.left = ggplot2::element_text(
      size = 12,
      color = "black",
      face = "bold",
      angle = 0,
      hjust = 0,
      family = "Arial"
    ),
    strip.text.x = ggplot2::element_text(
      size = 13,
      color = "black",
      face = "bold",
      family = "Arial"
    ),
    strip.placement = "outside",
    panel.spacing.x = grid::unit(1.0, "lines"),
    panel.spacing.y = grid::unit(0.8, "lines")
  ) +
  ggplot2::coord_cartesian(clip = "off")

save_plot(
  combined_plot,
  "mrna_go_enrichment_bar_combined",
  width = 17,
  height = 10
)

message("[plot] GO template figures complete.")
